# ---- THE READBACK ON THE KIN — THE LAWS' FORM (L1-L6 of 3b) RUN ON ANOTHER CHAPTER'S CODE: the row's first telling is a KIN CELL graded by CALL (cell, cell_found)
# or a tape line found by kind and first verse (tape_kind, tape_verse); every row a REFERENCE ROW (R1 — never a second write); what has no first telling is THE CODE'S HOLE ----
GRADES = ('VERBATIM', 'VARIANT', 'TURNED', 'SHORTENED', 'EXPANDED', 'SUPPLIED', 'DISAGREES')
def rb(verses, told, grade, why, tape_kind=None, tape_verse=None, cell=None, cell_found=None, entry='', open_=False):
    assert grade in GRADES, grade
    assert (tape_kind is None) != (cell is None), ('one of the tape or the cell', verses)
    if cell is not None: assert cell_found is True, ('the kin cell CALLED and found', verses, cell)
    return {'verses': verses, 'told': told, 'tape_kind': tape_kind, 'tape_verse': tape_verse, 'cell': cell, 'cell_found': cell_found, 'entry': entry, 'grade': grade, 'why': why, 'open': open_, 'law': True}
